#include <iostream>
#include <string>
#include <vector>
#include <utility>
// 입력은 서로 같은 길이의 ASCII 행이며 빈 격자도 허용합니다.
void Fill(std::vector<std::string>& g, int sr, int sc, char color) {
    const int rows=static_cast<int>(g.size());
    if(rows==0) return;
    const int cols=static_cast<int>(g[0].size());
    if(sr<0||sc<0||sr>=rows||sc>=cols) return;
    const char old=g[sr][sc];
    if(old==color) return; // 같은 색이면 방문 표시가 되지 않으므로 즉시 종료
    std::vector<std::pair<int,int> > todo;
    g[sr][sc]=color; todo.push_back(std::make_pair(sr,sc));
    const int dr[4]={-1,1,0,0}, dc[4]={0,0,-1,1};
    for(std::size_t i=0;i<todo.size();++i) {
        const int r=todo[i].first, c=todo[i].second;
        for(int k=0;k<4;++k) {
            const int nr=r+dr[k], nc=c+dc[k];
            if(nr>=0&&nc>=0&&nr<rows&&nc<cols&&g[nr][nc]==old) {
                g[nr][nc]=color; // 발견 즉시 표시하여 중복 등록 방지
                todo.push_back(std::make_pair(nr,nc));
            }
        }
    }
}
int main() {
    int rows,cols,sr,sc; char color;
    if(!(std::cin>>rows>>cols>>sr>>sc>>color)||rows<0||cols<0||rows>100||cols>100) return 1;
    std::vector<std::string> g(static_cast<std::size_t>(rows));
    for(int r=0;r<rows;++r) {
        if(cols>0 && !(std::cin>>g[r])) return 1;
        if(static_cast<int>(g[r].size())!=cols) return 1;
        for(char x:g[r]) if(x!='A'&&x!='B'&&x!='C') return 1;
    }
    if(color!='A'&&color!='B'&&color!='C') return 1;
    Fill(g,sr,sc,color);
    for(const std::string& row:g) std::cout<<row<<'\n';
}
